CREATE TABLE students (
  id INTEGER PRIMARY KEY,
  name VARCHAR(50) NOT NULL,
  class_id INTEGER
);

CREATE TABLE orders (
  id INTEGER PRIMARY KEY,
  student_id INTEGER REFERENCES students(id),
  amount NUMERIC NOT NULL
);

