SELECT name
FROM students
WHERE score = NULL;

SELECT id, amount
FROM orders
WHERE CAST(created_at AS DATE) = DATE '2026-01-01';

SELECT COUNT(*)
FROM orders o
JOIN order_items i ON i.order_id = o.id;
